const b = $json.body || $json;
const negocio = String(b.negocio || b.slug || '').trim();
const cliente = String(b.cliente || b.nombre || '').trim();
const whatsapp = String(b.whatsapp || b.from || '').trim();
const items = b.items || b.pedido || b.texto || '';
const nota = String(b.nota || '').trim();
if (!negocio) return [{ json: { ok: false, error: 'falta negocio' } }];
if (!whatsapp && !cliente) return [{ json: { ok: false, error: 'falta cliente/whatsapp' } }];
const ticket = `P-${Date.now().toString().slice(-6)}`;
return [{ json: {
  ok: true,
  sistema: '08-cola-pedidos-wasap',
  etapa: 'nuevo_pedido',
  ticket,
  negocio,
  cliente,
  whatsapp,
  items,
  nota,
  estado: 'nuevo',
  status: 'en_cola',
  todo: 'TODO: guardar en Sheet/Notion + ack al cliente',
  at: new Date().toISOString()
}}];
